import React, { useState, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

const ChatList = () => {
    const [chatRooms, setChatRooms] = useState([]);
    const [newRoomName, setNewRoomName] = useState('');
    const navigate = useNavigate();
    const stompClient = useRef(null);
    const userId = localStorage.getItem('userId');

    useEffect(() => {
        fetchChatRooms();
        connectToWebSocket();

        return () => {
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, []);

    const fetchChatRooms = async () => {
        const url = `http://172.30.1.52:8081/api/chatrooms`;
        try {
            console.log('Fetching chat rooms from:', url);
            const response = await axios.get(url);
            console.log('Response data:', response.data);

            if (Array.isArray(response.data)) {
                const chatRoomsData = response.data;

                const chatRoomsWithMessages = await Promise.all(
                    chatRoomsData.map(async (room) => {
                        const messagesResponse = await axios.get(
                            `http://172.30.1.52:8081/api/chatrooms/${room.id}/messages`
                        );
                        return { ...room, messages: messagesResponse.data };
                    })
                );
                setChatRooms(chatRoomsWithMessages);
            } else {
                console.error('Unexpected response data format:', response.data);
            }
        } catch (error) {
            console.error('Failed to fetch chat rooms:', error);
        }
    };

    const connectToWebSocket = () => {
        const socket = new SockJS('http://172.30.1.52:8081/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                console.log('Connected to WebSocket');
                stompClient.current.subscribe('/topic/public', (message) => {
                    const newMessage = JSON.parse(message.body);
                    setChatRooms((prevChatRooms) => {
                        const chatRoom = prevChatRooms.find((room) => room.id === newMessage.roomId);
                        if (chatRoom) {
                            chatRoom.messages.push(newMessage);
                        } else {
                            fetchChatRooms();
                        }
                        return [...prevChatRooms];
                    });
                });
            },
            onStompError: (frame) => {
                console.error('Broker reported error: ' + frame.headers['message']);
                console.error('Additional details: ' + frame.body);
            },
        });

        stompClient.current.activate();
    };

    const createChatRoom = async () => {
        if (newRoomName.trim()) {
            try {
                const response = await axios.post('http://172.30.1.52:8081/api/chatrooms', { name: newRoomName });
                const newChatRoom = { ...response.data, messages: [] };
                setChatRooms((prevChatRooms) => [...prevChatRooms, newChatRoom]);
                setNewRoomName('');
            } catch (error) {
                console.error('Failed to create chat room:', error);
            }
        }
    };

    const deleteChatRoom = async (roomId) => {
        try {
            await axios.delete(`http://172.30.1.52:8081/api/chatrooms/${roomId}`);
            setChatRooms((prevChatRooms) => prevChatRooms.filter((room) => room.id !== roomId));
        } catch (error) {
            console.error('Failed to delete chat room:', error);
        }
    };

    const startChatting = async () => {
        const defaultRoom = chatRooms.find((room) => room.name === 'Default Room');
        let roomId = defaultRoom ? defaultRoom.id : null;

        if (!roomId) {
            try {
                const response = await axios.post('http://172.30.1.52:8081/api/chatrooms', { name: 'Default Room' });
                roomId = response.data.id;
                setChatRooms((prevChatRooms) => [...prevChatRooms, { ...response.data, messages: [] }]);
            } catch (error) {
                console.error('Failed to create default chat room:', error);
                return;
            }
        }

        navigate(`/chatroom/${roomId}/Default Room`);
    };

    const renderItem = (item) => (
        <div
            key={item.id}
            style={{
                padding: '20px',
                borderBottom: '1px solid #ccc',
                display: 'flex',
                justifyContent: 'space-between',
                alignItems: 'center',
            }}
        >
            <div onClick={() => navigate(`/chatroom/${item.id}/${item.name}`)}>
                <h3>{item.name}</h3>
                {item.messages && item.messages.length > 0 && <p>{item.messages[item.messages.length - 1].content}</p>}
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
                <button onClick={() => navigate(`/chatroom/${item.id}/${item.name}`)}>Enter</button>
                <button onClick={() => deleteChatRoom(item.id)}>Delete</button>
            </div>
        </div>
    );

    return (
        <div style={{ padding: '10px' }}>
            <div style={{ marginBottom: '20px' }}>
                <input
                    type="text"
                    value={newRoomName}
                    onChange={(e) => setNewRoomName(e.target.value)}
                    placeholder="Enter room name"
                    style={{ padding: '10px', marginRight: '10px' }}
                />
                <button onClick={createChatRoom}>Create Chat Room</button>
            </div>
            <div style={{ marginBottom: '20px' }}>
                <button onClick={startChatting}>Start Chatting</button>
            </div>
            {chatRooms.map(renderItem)}
        </div>
    );
};

export default ChatList;
